 return {api,app,body,details,calls,confirmations,artifacts,defaultReply,get response(){return response;},set response(value){response=value;},set handler(value){handler=value;},set confirmHandler(value){confirmHandler=value;},find:label=>walk(body).find(item=>item.tagName==="BUTTON"&&item.textContent===label),field:name=>walk(body).find(item=>item.name===name),writes:()=>calls.filter(item=>item.options?.method==="POST")};
